use std::{env, fs, path::PathBuf};

use ts_rs::TS;
use xiic_book_studio_lib::{contracts::V2_COMMANDS, models::*};

fn declaration<T: TS>() -> String {
    let declaration = T::decl().replace("bigint", "number");
    format!("{}\n\n", declaration.replacen("type ", "export type ", 1))
}

fn render() -> String {
    let mut output = String::from(
        "// @generated by src-tauri/src/bin/generate_contracts.rs\n// Do not edit by hand. Run `npm run contracts:generate`.\n\n",
    );
    output.push_str(&declaration::<Stage>());
    output.push_str(&declaration::<ReferenceTag>());
    output.push_str(&declaration::<ReferenceSelection>());
    output.push_str(&declaration::<Project>());
    output.push_str(&declaration::<GenreAgentProfile>());
    output.push_str(&declaration::<Chapter>());
    output.push_str(&declaration::<Artifact>());
    output.push_str(&declaration::<WorkflowRun>());
    output.push_str(&declaration::<WorkflowRunSummary>());
    output.push_str(&declaration::<Approval>());
    output.push_str(&declaration::<Message>());
    output.push_str(&declaration::<StoryThread>());
    output.push_str(&declaration::<KnowledgeCard>());
    output.push_str(&declaration::<Foreshadowing>());
    output.push_str(&declaration::<StoryEntity>());
    output.push_str(&declaration::<StoryEvent>());
    output.push_str(&declaration::<StoryEventParticipant>());
    output.push_str(&declaration::<StoryFact>());
    output.push_str(&declaration::<StoryIndexSource>());
    output.push_str(&declaration::<StorySearchSource>());
    output.push_str(&declaration::<DerivedIndexJob>());
    output.push_str(&declaration::<AdoptionProposal>());
    output.push_str(&declaration::<StoryBible>());
    output.push_str(&declaration::<StoryArc>());
    output.push_str(&declaration::<CanonIssue>());
    output.push_str(&declaration::<StoryBibleReview>());
    output.push_str(&declaration::<AiSettings>());
    output.push_str(&declaration::<ToolKind>());
    output.push_str(&declaration::<AgentToolDefinition>());
    output.push_str(&declaration::<ToolProtocol>());
    output.push_str(&declaration::<AgentRunRequest>());
    output.push_str(&declaration::<ContextSegment>());
    output.push_str(&declaration::<PreparedContext>());
    output.push_str(&declaration::<ToolCall>());
    output.push_str(&declaration::<ToolResult>());
    output.push_str(&declaration::<ToolInvocation>());
    output.push_str(&declaration::<ProposalStatus>());
    output.push_str(&declaration::<ActionProposal>());
    output.push_str(&declaration::<ProposalApplyResult>());
    output.push_str(&declaration::<ProviderCapabilities>());
    output.push_str(&declaration::<AgentRunSummary>());
    output.push_str(&declaration::<RunEvent>());
    output.push_str(&declaration::<ActiveAgentRun>());
    output.push_str(&declaration::<ArtifactSummary>());
    output.push_str(&declaration::<ProjectWorkspace>());
    output.push_str("export const V2_COMMANDS = {\n");
    for (key, command) in V2_COMMANDS {
        output.push_str(&format!("  {key}: \"{command}\",\n"));
    }
    output.push_str("} as const;\n");
    output
}

fn main() {
    let destination = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("src")
        .join("generated")
        .join("v2-contracts.ts");
    let rendered = render();
    if env::args().any(|argument| argument == "--check") {
        let current = fs::read_to_string(&destination).unwrap_or_default();
        if current != rendered {
            eprintln!(
                "generated contracts are stale: {} (run npm run contracts:generate)",
                destination.display()
            );
            std::process::exit(1);
        }
        return;
    }
    fs::create_dir_all(destination.parent().expect("generated contracts parent"))
        .expect("create generated contracts directory");
    fs::write(&destination, rendered).expect("write generated TypeScript contracts");
}
